const rehireRaw = items[0].json?.message || null;

const mapping = {
  'The information is not available in the database.': 'No',
  'The candidate is not eligible for rehire.': 'No recontratable',
  'The candidate is eligible for rehire.': 'Sí'
};

const rehire = mapping[rehireRaw] || "Error al buscar datos para recontratación";

return [
  {
    json: {
      Rehire: rehire
    }
  }
];

return items[0].json.content.map(result => {
  return {
    application_id: result.application_id,
    content_id: result.id,
    stage: result.stage_task.stage.name,
    stage_task_id: result.stage_task.id,
    approval_status: result.approval_status,
    is_completed: result.is_completed,
    is_approved: result.is_approved
  };
});

const mapping = {
  "Soltera/o": 1,
  "Casada/o": 0,
  "Viudo": 3,
  "Divorciado/a": 2,
  "Separado": 100,
  "Unión libre": 5,
};

const item = items[0].json;
item.marital_status = mapping[item['Estado civil']] || 1;

return [{ 
  marital_status_code: item.marital_status }];

